import{_ as t,o,c as a,ag as s}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/sheets/build-a-budget-difference.png",l="/docs/images/sheets/build-a-budget-final.png",m=JSON.parse('{"title":"Build a budget","description":"Build a monthly budget that totals your spending, flags overspending, and formats the amounts as currency.","frontmatter":{"title":"Build a budget","description":"Build a monthly budget that totals your spending, flags overspending, and formats the amounts as currency.","type":"tutorial"},"headers":[],"relativePath":"sheets/build-a-budget.md","filePath":"sheets/build-a-budget.md"}'),r={name:"sheets/build-a-budget.md"};function i(d,e,c,h,g,u){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="build-a-budget" tabindex="-1">Build a budget <a class="header-anchor" href="#build-a-budget" aria-label="Permalink to &quot;Build a budget&quot;">​</a></h1><p>Build a monthly budget that totals your spending, flags overspending, and formats the amounts as currency. It takes about 10 minutes.</p><p>You will use <code>SUM</code>, a formula filled down a column, <code>IF</code>, number formats, and a conditional formatting rule.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need a Wafflebase account and a workspace where you can create documents.</li><li>Use a desktop browser. On a phone the fill handle is hidden and several tools move to the ⋮ menu.</li></ul></div><h2 id="_1-create-the-sheet" tabindex="-1">1. Create the sheet <a class="header-anchor" href="#_1-create-the-sheet" aria-label="Permalink to &quot;1. Create the sheet&quot;">​</a></h2><ol><li>In your workspace, click <strong>New</strong> and select <strong>New sheet</strong>.</li><li>Click cell <strong>A1</strong>.</li><li>Copy the data below and press <code>⌘+V</code> / <code>Ctrl+V</code> to paste it.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Category	Budget	Actual</span></span>
<span class="line"><span>Rent	1500	1500</span></span>
<span class="line"><span>Groceries	400	380</span></span>
<span class="line"><span>Transport	200	220</span></span>
<span class="line"><span>Utilities	150	135</span></span>
<span class="line"><span>Entertainment	100	95</span></span>
<span class="line"><span>Savings	500	500</span></span></code></pre></div><p>The data fills <strong>A1:C7</strong>, one value per cell.</p><h2 id="_2-add-totals" tabindex="-1">2. Add totals <a class="header-anchor" href="#_2-add-totals" aria-label="Permalink to &quot;2. Add totals&quot;">​</a></h2><ol><li><p>Click cell <strong>A8</strong> and type <code>Total</code>.</p></li><li><p>Click cell <strong>B8</strong>, type the formula below, and press <code>Enter</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=SUM(B2:B7)</span></span></code></pre></div></li><li><p>Click cell <strong>C8</strong>, type <code>=SUM(C2:C7)</code>, and press <code>Enter</code>.</p></li></ol><p><strong>B8</strong> shows <code>2850</code> and <strong>C8</strong> shows <code>2830</code>.</p><h2 id="_3-calculate-the-difference" tabindex="-1">3. Calculate the difference <a class="header-anchor" href="#_3-calculate-the-difference" aria-label="Permalink to &quot;3. Calculate the difference&quot;">​</a></h2><ol><li>Click cell <strong>D1</strong> and type <code>Difference</code>.</li><li>Click cell <strong>D2</strong>, type <code>=B2-C2</code>, and press <code>Enter</code>.</li><li>Drag across <strong>D2:D8</strong> to select the range.</li><li>Press <code>⌘+D</code> / <code>Ctrl+D</code> to fill down.</li></ol><p>Each row now subtracts its own actual from its budget. The references change row by row: <strong>D3</strong> holds <code>=B3-C3</code>, and <strong>D8</strong> shows the total difference, <code>20</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can also drag the fill handle, the small square at the bottom-right corner of the selection, from <strong>D2</strong> down to <strong>D8</strong>.</p></div><p><img src="`+n+'" alt="Budget sheet with a Difference column; Transport shows -20 and the Total row shows 20"></p><h2 id="_4-flag-overspending" tabindex="-1">4. Flag overspending <a class="header-anchor" href="#_4-flag-overspending" aria-label="Permalink to &quot;4. Flag overspending&quot;">​</a></h2><ol><li><p>Click cell <strong>E1</strong> and type <code>Status</code>.</p></li><li><p>Click cell <strong>E2</strong>, type the formula below, and press <code>Enter</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>=IF(D2&lt;0, &quot;Over&quot;, &quot;OK&quot;)</span></span></code></pre></div></li><li><p>Select <strong>E2:E7</strong> and press <code>⌘+D</code> / <code>Ctrl+D</code>.</p></li></ol><p><strong>E4</strong>, the Transport row, shows <code>Over</code>. Every other row shows <code>OK</code>.</p><h2 id="_5-format-the-numbers" tabindex="-1">5. Format the numbers <a class="header-anchor" href="#_5-format-the-numbers" aria-label="Permalink to &quot;5. Format the numbers&quot;">​</a></h2><ol><li>Select <strong>B2:D8</strong>.</li><li>Click <strong>Format as currency</strong> in the toolbar. Its tooltip names your local currency, for example <strong>Format as currency (USD)</strong>.</li><li>Click cell <strong>A10</strong> and type <code>Used</code>.</li><li>Click cell <strong>B10</strong>, type <code>=C8/B8</code>, and press <code>Enter</code>.</li><li>With <strong>B10</strong> selected, click <strong>Format as percent</strong>.</li></ol><p>The amounts show as currency, such as <code>$1,500.00</code> and <code>-$20.00</code>. <strong>B10</strong> shows <code>99.30%</code> of the budget used.</p><h2 id="_6-highlight-the-rows-that-are-over-budget" tabindex="-1">6. Highlight the rows that are over budget <a class="header-anchor" href="#_6-highlight-the-rows-that-are-over-budget" aria-label="Permalink to &quot;6. Highlight the rows that are over budget&quot;">​</a></h2><ol><li>Select <strong>E2:E7</strong>.</li><li>Click <strong>Conditional formatting</strong> in the toolbar. The panel opens with a new rule for <strong>E2:E7</strong>.</li><li>Under <strong>Format rules</strong>, select <strong>Text contains</strong>.</li><li>In the value box, type <code>Over</code>.</li><li>Click <strong>Done</strong>.</li></ol><p>The <code>Over</code> cell turns light green. To pick another color, change <strong>Background color</strong> under <strong>Formatting style</strong> before you click <strong>Done</strong>.</p><p>Your sheet should look like this:</p><p><img src="'+l+'" alt="Finished budget in currency format; Transport is marked Over and highlighted, and B10 shows 99.30% used"></p><h2 id="what-you-learned" tabindex="-1">What you learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What you learned&quot;">​</a></h2><ul><li><code>SUM</code> adds a range, and a relative reference such as <code>B2</code> adjusts when you fill it down.</li><li><code>IF</code> returns one value or another based on a condition.</li><li>Number formats and conditional formatting change how values look without changing them.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/sheets/formulas.html">Formulas</a> to reference other tabs and find more functions.</li><li><a href="/docs/sheets/charts.html">Charts</a> to chart your budget against actual spending.</li><li><a href="/docs/collaborate/share.html">Share a document</a> to plan the budget with someone else.</li></ul>',31)])])}const b=t(r,[["render",i]]);export{m as __pageData,b as default};
